        }
      ],
      "confianca": 0.98,
      "justificativa": "Três ramos com a mesma locução verbal (ha de concorrer), diferenciando os três agentes (S) e seus respectivos meios/modos de concurso (C)."
    },
    {
      "paragrafo_id": "239684-p009",
      "categoria": "nuclear",
      "G": "concorre",
      "G_lema": "concorrer",
      "ramos": [
        {
          "S": "O prégador",
          "C": "com o espelho, que é a doutrina",
          "G_elidido": false,
          "G_forma": "concorre",
          "S_referente": "distinto",
          "C_funcao": "argumental"
        },
        {
          "S": "Deus",
          "C": "com a luz, que é a graça",
          "G_elidido": false,
          "G_forma": "concorre",
          "S_referente": "distinto",
          "C_funcao": "argumental"
        },
        {
          "S": "o homem",
          "C": "com os olhos, que é o conhecimento",
          "G_elidido": false,
          "G_forma": "concorre",
          "S_referente": "distinto",
          "C_funcao": "argumental"
        }
      ],
      "confianca": 0.98,
      "justificativa": "Três ramos paralelos com o verbo pleno 'concorre' invariante, distribuindo diferentes sujeitos (S) e seus instrumentos metafóricos (C)."
    }
  ],
  "quase_casos": [
    {
      "paragrafo_id": "239684-p009",
      "trecho": "Se tem espelho e é cégo, não se póde vêr por falta de olhos; se tem espelho e olhos, e é de noite, não se póde vêr por falta de luz.",
      "tipo": "variacao_simples",
      "motivo": "O sujeito ('um homem' implícito) tem o mesmo referente nos dois ramos; varia apenas a condição e a causa."
    },
    {
      "paragrafo_id": "239684-p009",
      "trecho": "Logo ha mister luz, ha mister espelho, e ha mister olhos.",
      "tipo": "variacao_simples",
      "motivo": "Apenas o objeto varia; não há diferenciador S distinto em cada ramo."
    },
    {
      "paragrafo_id": "239684-p009",
      "trecho": "Para esta vista são necessarios olhos, é necessaria luz, e é necessario espelho.",
      "tipo": "variacao_simples",
      "motivo": "Varia o sujeito, mas o predicativo ('necessarios'/'necessaria'/'necessario') é o mesmo, variando apenas em concordância."
    },
    {
      "paragrafo_id": "239684-p010",
      "trecho": "Do trigo que deitou á terra o semeador, uma parte se logrou, e tres se perderam.",
      "tipo": "verbo_variavel",
      "motivo": "Os verbos ('se logrou' / 'se perderam') têm lemas diferentes."
    },
    {
      "paragrafo_id": "239684-p010",
      "trecho": "A primeira perdeu-se, porque a afogaram os espinhos; a segunda, porque a secaram as pedras; a terceira, porque a pisaram os homens, e a comeram as aves.",
      "tipo": "outro",
      "motivo": "Com G='perdeu-se', os diferenciadores seriam orações causais ('porque...'), que pelas regras não constituem locus C."
    },
    {
      "paragrafo_id": "239684-p010",
      "trecho": "Deixará de fructificar a sementeira, ou pelo embaraço dos espinhos, ou pela dureza das pedras, ou pelos descaminhos dos caminhos",
      "tipo": "variacao_simples",
      "motivo": "Um único sujeito ('a sementeira') para três causas alternativas; não há variação de S."
    },
    {
      "paragrafo_id": "239684-p010",
      "trecho": "Sempre Deus está prompto de sua parte, com o sol pará aquentar, a com a chuva para regar; com o sol para allumiar, e com a chuva para amollecer",
      "tipo": "variacao_simples",
      "motivo": "O sujeito ('Deus') é único; variam apenas os adjuntos instrumentais e finais."
    }
  ]
}

