  "quase_casos": [
    {
      "paragrafo_id": "239684-p039",
      "trecho": "Não gostem, e abrandem-se; não gostem, e quebrem-se; não gostem, e fructifiquem.",
      "tipo": "anafora",
      "motivo": "Repetição anafórica de 'não gostem' seguida de verbos diferentes em gradação, com o mesmo sujeito implícito."
    },
    {
      "paragrafo_id": "239684-p039",
      "trecho": "A prégação que fructifica, a prégação que aproveita, não é aquella que dá gosto ao ouvinte, é aquella que lhe dá pena.",
      "tipo": "antitese",
      "motivo": "Oposição predicativa sobre o mesmo sujeito ('A prégação'), variando apenas a polaridade da cópula e o complemento."
    },
    {
      "paragrafo_id": "239684-p040",
      "trecho": "Quando oiço um, sáio do sermão muito contente do prégador; quando oiço outro, sáio muito descontente de mim.",
      "tipo": "variacao_simples",
      "motivo": "O sujeito de 'oiço' e 'sáio' é idêntico nos dois ramos (1ª pessoa); variam apenas as circunstâncias e predicativos."
    },
    {
      "paragrafo_id": "239684-p040",
      "trecho": "não que lhes pareçam bem os nossos conceitos, mas que lhes pareçam mal os seus costumes",
      "tipo": "antitese",
      "motivo": "Estrutura antitética com polaridade oposta ('não que... mas que') e advérbios contrários ('bem' / 'mal') integrados ao predicado."
    },
    {
      "paragrafo_id": "239684-p040",
      "trecho": "Préguemos, e armemo-nos todos contra os peccados, contra as soberbas, contra os odios, contra as ambições, contra as invejas, contra as cobiças, contra as sensualidades.",
      "tipo": "lista",
      "motivo": "Enumeração de complementos preposicionados para o mesmo sujeito ('todos') e os mesmos verbos."
    }
  ]
