  "quase_casos": [
    {
      "paragrafo_id": "189440-p029",
      "trecho": "É possivel que sinta tanto Christo o apartar -se de nós, e que haja bomens que não sintam o apartar -se de Christo",
      "tipo": "verbo_variavel",
      "motivo": "Contraste com inversão de polaridade (sinta vs. não sintam) e mudança de construção sintática (haja homens que...)."
    },
    {
      "paragrafo_id": "189440-p029",
      "trecho": "Christo sente tanto apartar -se de ti, indo para o céu : Ut transeat ex hoc mundo ad Patrem; e tu sentes tão pouco apartar-te de Christo, indo para o inferno ?",
      "tipo": "antitese",
      "motivo": "Antítese com quantificadores opostos (tanto vs. tão pouco) que alteram o predicado."
    },
    {
      "paragrafo_id": "189440-p029",
      "trecho": "Se como christão não te lembras de Christo , ao menos como homem , lembra-te de ti.",
      "tipo": "verbo_variavel",
      "motivo": "Mudança de modo verbal e polaridade entre os membros (indicativo negativo vs. imperativo afirmativo)."
    },
    {
      "paragrafo_id": "189440-p029",
      "trecho": "porque nem és christão, nem homem; nem tens fé, nem tens juiso.",
      "tipo": "variacao_simples",
      "motivo": "O sujeito é idêntico (tu) em todos os membros; variam apenas os predicativos e objetos."
    },
    {
      "paragrafo_id": "189440-p029",
      "trecho": "Esta é a hora de acabar com o mundo: Ut transeat ex hoc mundo. Esta é a hora de romper as cadêas desse máu vicio (qualquer que seja) que tão prezo te tem , e tanto le tyrannisa. Esta é a hora de acabar de conhecer, e te desenganar desse fado e enganoso amor. Esta é a hora de abrir os olhos a esse amor cego. Esta é a hora de reformar esse amor escandaloso. Esta é a hora de purificar esse amor impuro, e de o pôr todo em Christo.",
      "tipo": "anafora",
      "motivo": "Anáfora com o mesmo sujeito referencial ('Esta [hora]') em todos os membros, variando apenas a especificação."
    },
    {
      "paragrafo_id": "189440-p029",
      "trecho": "Ah, Senhor, como se ha de converter n'outra hora, quem se não converte a vós nesta hora vossa? Como vos ha de amar n'outra hora, quem vos não ama nesta hora de vosso amor?",
      "tipo": "verbo_variavel",
      "motivo": "Paralelismo interrogativo com verbos distintos em cada oração (converter vs. amar)."
    },
    {
      "paragrafo_id": "189440-p029",
      "trecho": "Basta um judas, basta um ingrato, basta um inimigo, basta um traidor.",
      "tipo": "variacao_simples",
      "motivo": "Anáfora com variação apenas do sujeito/termo pós-verbal, sem locus ou complemento C distinto."
    },
    {
      "paragrafo_id": "189440-p030",
      "trecho": "só a vós queremos amar, para nunca mais vos offender: só a vós queremos amar, para nunca mais vos ser ingratos: só a vós queremos amar, para nunca mais nos apartarmos de vós: só a vós queremos amar, para desta hora em diante nos apartarmos para sempre de tudo o que aparta de vosso amor.",
      "tipo": "anafora",
      "motivo": "Mesmo sujeito ('nós') e mesmo objeto ('só a vós') em todos os ramos, variando apenas a oração final."
    },
    {
      "paragrafo_id": "189440-p030",
      "trecho": "Seja esta hora o fim de todo o amor que não é vosso , e seja o principio de vos amarmos sem fim",
      "tipo": "variacao_simples",
      "motivo": "Mesmo sujeito ('esta hora') para ambos os predicativos opostos ('o fim...' e 'o principio...')."
    }
  ]
}
